    &mut self,
    parent: BlockNumHash,
) -> Result<(), InsertBlockFatalError> {
    let blocks = self.state.buffer.remove_block_with_children(&parent.hash);

    if blocks.is_empty() {
        // nothing to append
        return Ok(())
