}

fn insert_block(
    &mut self,
    block: RecoveredBlock<N::Block>,
) -> Result<InsertPayloadOk, InsertPayloadError<N::Block>> {
    self.insert_block_or_payload(
        block.block_with_parent(),
        block,
        |validator, block, ctx| validator.validate_block(block, ctx),
        |_, block| Ok(block),
    )
}

